# Custom CUDA kernel for inplace matrix multiplication
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * K) {
        // In-place multiplication: C = A @ B.T
        for k in range(K):
            C[idx * N + k] = A[idx * K + k] * B[k * N + k];
